  ('boga-signature', 'boga-signature', 'signature', '{"ar":"BOGA Signature","fr":"BOGA Signature","en":"BOGA Signature"}'::jsonb, '{"ar":"ناعمة، مدهشة ولذيذة","fr":"Doux, sensationnel et savoureux","en":"Smooth, sensational and flavourful"}'::jsonb, '{"ar":"خلطة الدار: أرابيكا البرازيل وهندوراس مع لمسة روبوستا من فيتنام لكريمة كثيفة وطعم متوازن يناسب الإسبريسو والقهوة بالحليب.","fr":"Le blend de la maison : les Arabica du Brésil et du Honduras, relevés d''une touche de Robusta du Viêt Nam pour une crema dense et un goût équilibré, en espresso comme avec du lait.","en":"The house blend: Brazilian and Honduran Arabica lifted by a touch of Vietnamese Robusta for a dense crema and a balanced cup, as espresso or with milk."}'::jsonb, 'medium', '{"ar":"شوكولاتة، كراميل، بندق محمّص","fr":"Chocolat, caramel, noisette grillée","en":"Chocolate, caramel, toasted hazelnut"}'::jsonb, '{"250":65,"500":120,"1000":225}'::jsonb, null, true, true, 1),
