  ('horeca-crema-forte', 'horeca-crema-forte', 'b2b', '{"ar":"HORECA Crema Forte","fr":"HORECA Crema Forte","en":"HORECA Crema Forte"}'::jsonb, '{"ar":"قوية واقتصادية، ممتازة مع الحليب","fr":"Corsé et économique, idéal avec du lait","en":"Strong and cost-effective, ideal with milk"}'::jsonb, '{"ar":"نسبة روبوستا عالية لقهوة قوية بتكلفة مضبوطة، مناسبة للمطاعم والفنادق وقهوة الحليب.","fr":"Une forte part de Robusta pour une tasse intense à coût maîtrisé : restaurants, hôtels et boissons lactées.","en":"A high Robusta share for an intense cup at a controlled cost: restaurants, hotels and milk drinks."}'::jsonb, 'dark', '{"ar":"شوكولاتة داكنة، خشب، كريمة كثيفة","fr":"Chocolat noir, boisé, crema épaisse","en":"Dark chocolate, woody, thick crema"}'::jsonb, '{"250":45,"500":80,"1000":150}'::jsonb, null, false, true, 21),
