insert into public.payment_methods (id, enabled, label, instructions)
values
  ('card', false, '{"ar":"بطاقة بنكية","fr":"Carte bancaire","en":"Bank card"}'::jsonb, '{"ar":"دفع آمن عبر صفحة CMI (3-D Secure). Visa و Mastercard والبطاقات المغربية.","fr":"Paiement sécurisé sur la page du CMI (3-D Secure). Visa, Mastercard et cartes marocaines.","en":"Secure payment on the CMI page (3-D Secure). Visa, Mastercard and Moroccan cards."}'::jsonb),
  ('cashplus', true, '{"ar":"كاش بلوس","fr":"Cash Plus","en":"Cash Plus"}'::jsonb, '{"ar":"أرسل المبلغ عبر وكالة كاش بلوس باسم المستفيد أدناه مع رقم الطلب، ثم أرسل صورة الوصل على واتساب.","fr":"Envoyez le montant depuis une agence Cash Plus au bénéficiaire ci-dessous avec le numéro de commande, puis envoyez la photo du reçu sur WhatsApp.","en":"Send the amount from a Cash Plus agency to the beneficiary below with the order number, then send a photo of the receipt on WhatsApp."}'::jsonb),
  ('bank_transfer', true, '{"ar":"تحويل بنكي","fr":"Virement bancaire","en":"Bank transfer"}'::jsonb, '{"ar":"قم بالتحويل إلى الحساب أدناه مع ذكر رقم الطلب. نبدأ التحضير فور وصول المبلغ.","fr":"Faites un virement vers le compte ci-dessous en indiquant le numéro de commande. La préparation commence dès réception.","en":"Transfer to the account below with the order number as reference. Preparation starts as soon as it arrives."}'::jsonb)
on conflict (id) do nothing;

insert into public.site_config (id, settings, content)
values (1, '{"currency":"MAD","b2bThresholdKg":10,"customBlend":{"enabled":true,"minPercent":5,"maxOrigins":4,"feeBySize":{"250":10,"500":15,"1000":20}},"roastLossPercent":0,"freeShippingOver":0,"unpaidOrderTimeoutHours":48,"paymentCheckTimeoutHours":120,"contact":{"whatsapp":"+212609036378","email":"bogacafe1@gmail.com","instagram":"https://www.instagram.com/boga.cafe1","tiktok":"https://www.tiktok.com/@bogacafe795","facebook":"https://www.facebook.com/profile.php?id=61594620729419","address":{"ar":"وجدة، المغرب","fr":"Oujda, Maroc","en":"Oujda, Morocco"},"hours":{"ar":"كل يوم، من 8:00 إلى 22:00","fr":"Tous les jours, de 8 h à 22 h","en":"Every day, 8 am to 10 pm"}},"bank":{"holder":"","bankName":"","rib":""},"cashplus":{"beneficiary":""}}'::jsonb, '{"announcement":{"ar":"توصيل لجميع مدن المغرب · قهوة حبوب فقط · محمّصة خصيصاً لـ BOGA CAFÉ","fr":"Livraison dans tout le Maroc · Café en grains uniquement · Torréfié pour BOGA CAFÉ","en":"Delivery across Morocco · Whole beans only · Roasted for BOGA CAFÉ"},"heroTitle":{"ar":"قهوة حبوب، محمّصة من أجلك.","fr":"Café en grains, torréfié pour vous.","en":"Whole-bean coffee, roasted for you."},"heroSubtitle":{"ar":"خلطات مميزة، قهوة أحادية المصدر، وخلطة خاصة تركّبها بنفسك. من وجدة، مع التوصيل لكل مدن المغرب.","fr":"Blends signature, single origin et un Custom Blend que vous composez vous-même. Depuis Oujda, livré partout au Maroc.","en":"Signature blends, single origins and a Custom Blend you compose yourself. From Oujda, delivered across Morocco."},"aboutTitle":{"ar":"علامتنا، وصفاتنا، وتحميص حسب مواصفاتنا","fr":"Nos recettes, notre marque, une torréfaction sur cahier des charges","en":"Our recipes, our brand, roasted to our specification"},"aboutText":{"ar":"تحدد BOGA CAFÉ وصفاتها ونسب خلطاتها ومواصفات كل منتج، ويقوم شريكنا المحمّص بالتحميص وفق هذه المواصفات بالضبط. بعد ذلك تُعبّأ القهوة في أكياس BOGA CAFÉ وتصلك حبوباً كاملة لتحافظ على نكهتها.","fr":"BOGA CAFÉ définit ses recettes, ses proportions et les spécifications de chaque produit. Notre torréfacteur partenaire torréfie exactement selon ce cahier des charges, puis le café est conditionné dans les sachets BOGA CAFÉ et vous arrive en grains entiers pour garder tous ses arômes.","en":"BOGA CAFÉ defines its recipes, proportions and the specification of every product. Our partner roaster roasts exactly to that specification, then the coffee is packed in BOGA CAFÉ bags and reaches you as whole beans to keep every aroma."}}'::jsonb)
on conflict (id) do nothing;

